def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or (len(part) > 1 and part[0] == '0') or not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True
```

